CREATE TEMPORARY VIEW shop_data_${grass_region_without_quote} AS
SELECT
     shop_id
    ,shop_type
FROM srdi_mart.dim_sr_data_warehouse_shop
WHERE local_date = ${local_date} and grass_region IN (${grass_region})
AND shop_id > 0
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW item_data_${grass_region_without_quote} AS
SELECT
     item_id
    ,shop_id
    ,level1_global_be_category_id
    ,level2_global_be_category_id
    ,level3_global_be_category_id
    ,level4_global_be_category_id
    ,level5_global_be_category_id
    ,level1_global_be_category
    ,level2_global_be_category
    ,level3_global_be_category
    ,level4_global_be_category
    ,level5_global_be_category
FROM srdi_mart.dim_sr_data_warehouse_item
WHERE local_date = ${local_date} and grass_region IN (${grass_region})
AND shop_id > 0 and item_id>0
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW final_data_${grass_region_without_quote} AS
select
     *
    ,CASE 
        WHEN scenario_tag = 'DA_Search' THEN 'Search'
        WHEN scenario_tag = 'DA_mpp_ymal-order_list' THEN 'My Purchase Page YMAL'
        WHEN scenario_tag = 'DA_odp_ymal-order_detail' THEN 'Order Detail Page YMAL'
        WHEN scenario_tag = 'DA_Cart_Unify' THEN 'Cart Unify'
        WHEN scenario_tag LIKE 'DA_%' THEN split(scenario_tag,'_')[1]
        WHEN scenario_tag = '__ALL__' THEN '__ALL__'
    ELSE '' END AS feature_group
from union_data_${grass_region_without_quote}
;

--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_perf_${grass_region_without_quote} AS -- ads metrics
SELECT
    item_id
    ,feature_group
    ,is_roi2_item
    ,1 AS is_ads_item
FROM srdi_mart.dwm_sr_data_warehouse_ads_item_tag
WHERE local_date = ${local_date}
    AND grass_region in (${grass_region})
    AND item_id IS NOT NULL
    AND impression_cnt > 0
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_platform_item_level_benchmark_1d PARTITION (grass_region = ${grass_region}, local_date = ${local_date})
select /*+ REPARTITION(500) */
     platform
    ,b.shop_id
    ,is_ads
    ,a.item_id
    ,feature_detail
    ,scenario_tag
    ,c.shop_type
    ,level1_global_be_category_id
    ,level2_global_be_category_id
    ,level3_global_be_category_id
    ,level4_global_be_category_id
    ,level5_global_be_category_id
    ,level1_global_be_category
    ,level2_global_be_category
    ,level3_global_be_category
    ,level4_global_be_category
    ,level5_global_be_category
    ,imp_cnt
    ,click_cnt
    ,view_cnt
    ,ppv_cnt
    ,ppv_cnt_exclude_isback
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv
    ,omni_imp_cnt
    ,omni_click_cnt
    ,pc2_gmv
    ,is_ads_item
    ,is_roi2_item
from final_data_${grass_region_without_quote} a
left join item_data_${grass_region_without_quote} b on a.item_id=b.item_id
left join shop_data_${grass_region_without_quote} c on c.shop_id=b.shop_id
left join ads_perf_${grass_region_without_quote} d on a.item_id=d.item_id and a.feature_group=d.feature_group
where coalesce(a.item_id, 0) > 0

union all
select /*+ REPARTITION(200) */
     platform
    ,null as shop_id
    ,is_ads
    ,item_id
    ,feature_detail
    ,scenario_tag
    ,null as shop_type
    ,null as level1_global_be_category_id
    ,null as level2_global_be_category_id
    ,null as level3_global_be_category_id
    ,null as level4_global_be_category_id
    ,null as level5_global_be_category_id
    ,null as level1_global_be_category
    ,null as level2_global_be_category
    ,null as level3_global_be_category
    ,null as level4_global_be_category
    ,null as level5_global_be_category
    ,imp_cnt
    ,click_cnt
    ,view_cnt
    ,ppv_cnt
    ,ppv_cnt_exclude_isback
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv
    ,omni_imp_cnt
    ,omni_click_cnt
    ,pc2_gmv
    ,null as is_ads_item
    ,null as is_roi2_item
from union_data_${grass_region_without_quote}
where coalesce(item_id, 0) <= 0
